#include <algorithm>
#include <cstdio>
#include <iostream>
#include <map>
#include <utility>
#include <vector>

using namespace std;

map<pair<unsigned long long, int>, unsigned long long> memo;
vector<pair<unsigned long long, int>> items;
vector<unsigned long long> prefixSum;

unsigned long long solve(unsigned long long capacity, int index) {
    if (index == -1) return 0;
    if (capacity >= prefixSum[index]) return prefixSum[index];

    auto key = make_pair(capacity, index);
    auto it = memo.find(key);
    if (it != memo.end()) return it->second;

    unsigned long long answer = solve(capacity, index - 1);

    for (int count = 1; count <= items[index].second; ++count) {
        unsigned long long value = items[index].first * count;
        if (value <= capacity) {
            answer = max(answer, value + solve(capacity - value, index - 1));
        }
    }

    return memo[key] = answer;
}

int main() {
    unsigned long long capacity;
    scanf("%llu", &capacity);

    map<unsigned long long, unsigned long long> counts;
    for (int value = 1; value <= 8; ++value) {
        unsigned long long count;
        scanf("%llu", &count);
        counts[value] = count;
    }

    while (!counts.empty()) {
        auto [value, count] = *counts.begin();
        counts.erase(counts.begin());

        if (count == 0) continue;

        if (count <= 2) {
            items.emplace_back(value, static_cast<int>(count));
        } else if (count % 2 == 1) {
            items.emplace_back(value, 1);
            counts[value * 2] += count / 2;
        } else {
            items.emplace_back(value, 2);
            counts[value * 2] += (count - 2) / 2;
        }
    }

    unsigned long long sum = 0;
    for (const auto& [value, count] : items) {
        sum += value * count;
        prefixSum.push_back(sum);
    }

    cout << solve(capacity, static_cast<int>(items.size()) - 1) << '\n';
    return 0;
}

